fun binarySearch(nums: IntArray, target: Int): Int {
    var left = 0
    var right = nums.size - 1
    while (left <= right) {
        val mid = left + (right - left) / 2     // avoids Int overflow
        when {
            nums[mid] == target -> return mid
            nums[mid] < target -> left = mid + 1
            else -> right = mid - 1
        }
    }
    return -1
}
// Time: O(log n)   Space: O(1)

fun lowerBound(nums: IntArray, target: Int): Int {
    var left = 0
    var right = nums.size          // right = size means 'not found' is possible
    while (left < right) {
        val mid = left + (right - left) / 2
        if (nums[mid] >= target) right = mid     // mid may be the answer, keep it
        else left = mid + 1
    }
    return left                    // size if every element is smaller
}
// Time: O(log n)   Space: O(1)

fun upperBound(nums: IntArray, target: Int): Int {
    var left = 0
    var right = nums.size
    while (left < right) {
        val mid = left + (right - left) / 2
        if (nums[mid] > target) right = mid
        else left = mid + 1
    }
    return left
}
// First index of target = lowerBound, last index = upperBound - 1
// Count of target = upperBound - lowerBound

// Works whenever the answers look like: false false false true true true
fun findFirstTrue(low: Int, high: Int, isTrue: (Int) -> Boolean): Int {
    var left = low
    var right = high                // high should be a value known to be true
    while (left < right) {
        val mid = left + (right - left) / 2
        if (isTrue(mid)) right = mid
        else left = mid + 1
    }
    return left
}

fun searchInsert(nums: IntArray, target: Int): Int {
    var left = 0
    var right = nums.size
    while (left < right) {
        val mid = left + (right - left) / 2
        if (nums[mid] >= target) right = mid else left = mid + 1
    }
    return left
}
// Time: O(log n)   Space: O(1)

fun searchRange(nums: IntArray, target: Int): IntArray {
    fun lower(t: Int): Int {
        var l = 0
        var r = nums.size
        while (l < r) {
            val m = l + (r - l) / 2
            if (nums[m] >= t) r = m else l = m + 1
        }
        return l
    }
    val first = lower(target)
    if (first == nums.size || nums[first] != target) return intArrayOf(-1, -1)
    val last = lower(target + 1) - 1
    return intArrayOf(first, last)
}
// Time: O(log n)   Space: O(1)

fun searchRotated(nums: IntArray, target: Int): Int {
    var left = 0
    var right = nums.size - 1
    while (left <= right) {
        val mid = left + (right - left) / 2
        if (nums[mid] == target) return mid
        if (nums[left] <= nums[mid]) {                 // left half is sorted
            if (target >= nums[left] && target < nums[mid]) right = mid - 1
            else left = mid + 1
        } else {                                       // right half is sorted
            if (target > nums[mid] && target <= nums[right]) left = mid + 1
            else right = mid - 1
        }
    }
    return -1
}
// Time: O(log n)   Space: O(1)
// At least one half is always sorted

fun findMin(nums: IntArray): Int {
    var left = 0
    var right = nums.size - 1
    while (left < right) {
        val mid = left + (right - left) / 2
        if (nums[mid] > nums[right]) left = mid + 1    // minimum is on the right
        else right = mid                                // mid could be the minimum
    }
    return nums[left]
}
// Time: O(log n)   Space: O(1)
// Compare with nums[right], not nums[left]

fun findPeakElement(nums: IntArray): Int {
    var left = 0
    var right = nums.size - 1
    while (left < right) {
        val mid = left + (right - left) / 2
        if (nums[mid] < nums[mid + 1]) left = mid + 1   // climbing: peak is to the right
        else right = mid                                 // falling: peak is here or left
    }
    return left
}
// Time: O(log n)   Space: O(1)

fun peakIndexInMountainArray(arr: IntArray): Int {
    var left = 0
    var right = arr.size - 1
    while (left < right) {
        val mid = left + (right - left) / 2
        if (arr[mid] < arr[mid + 1]) left = mid + 1 else right = mid
    }
    return left
}
// Time: O(log n)   Space: O(1)

fun mySqrt(x: Int): Int {
    var left = 0
    var right = x
    var answer = 0
    while (left <= right) {
        val mid = left + (right - left) / 2
        if (mid.toLong() * mid <= x) {          // use Long to avoid overflow
            answer = mid                         // mid is a valid candidate
            left = mid + 1
        } else {
            right = mid - 1
        }
    }
    return answer
}
// Time: O(log x)   Space: O(1)

fun searchMatrix(matrix: Array<IntArray>, target: Int): Boolean {
    val rows = matrix.size
    val cols = matrix[0].size
    var left = 0
    var right = rows * cols - 1
    while (left <= right) {
        val mid = left + (right - left) / 2
        val value = matrix[mid / cols][mid % cols]     // flatten index
        when {
            value == target -> return true
            value < target -> left = mid + 1
            else -> right = mid - 1
        }
    }
    return false
}
// Time: O(log(rows * cols))   Space: O(1)

fun nextGreatestLetter(letters: CharArray, target: Char): Char {
    var left = 0
    var right = letters.size
    while (left < right) {
        val mid = left + (right - left) / 2
        if (letters[mid] > target) right = mid else left = mid + 1
    }
    return letters[left % letters.size]               // wrap around
}
// Time: O(log n)   Space: O(1)

fun singleNonDuplicate(nums: IntArray): Int {
    var left = 0
    var right = nums.size - 1
    while (left < right) {
        var mid = left + (right - left) / 2
        if (mid % 2 == 1) mid--                         // make mid even
        if (nums[mid] == nums[mid + 1]) left = mid + 2  // pairs are intact on the left
        else right = mid                                 // single is at mid or on the left
    }
    return nums[left]
}
// Time: O(log n)   Space: O(1)

